er-top:2px solid #FB4D30;wid=\r\nth:522px;\">\r\n          <tr>\r\n            <td style=3D\"height:0;line-height:0\">&nbsp;</td>\r\n          </tr>\r\n        </table>\r\n      <![endif]-->\r\n    </td>\r\n  </tr>\r\n</tbody></table></div></td></tr></tbody></table>\r\n  <table role=3D\"presentation\" cellpadding=3D\"0\" cellspacing=3D\"0\" width=3D=\r\n\"100%\" class=3D\"\" style=3D\"\"><tbody><tr><td class=3D\"hs_padded\" style=3D\"fo=\r\nnt-family:Arial, sans-serif; font-size:18px; color:#000000; word-break:brea=\r\nk-word; padding:20px 20px 10px\"><div id=3D\"hs_cos_wrapper_module-1-0-2\" cla=\r\nss=3D\"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module\" styl=\r\ne=3D\"color: inherit; font-size: inherit; line-height: inherit;\" data-hs-cos=\r\n-general-type=3D\"widget\" data-hs-cos-type=3D\"module\"><div id=3D\"hs_cos_wrap=\r\nper_module-1-0-2_\" class=3D\"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wra=\r\npper_type_rich_text\" style=3D\"color: inherit; font-size: inherit; line-heig=\r\nht: inherit;\" data-hs-cos-general-type=3D\"widget\" data-hs-cos-type=3D\"rich_=\r\ntext\"><p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #=\r\n000000;\">Picture this.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">It=E2=80=99s late. You=E2=80=99re brushing your teeth. The day starts re=\r\nplaying in your head.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">Notice what shows up.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">The awkward comment. The thing you didn=E2=80=99t finish. The decision y=\r\nou=E2=80=99re still second-guessing.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">That=E2=80=99s <a href=3D\"https://d586LZ04.na1.hubspotlinks.com/Ctc/W5+1=\r\n13/d586LZ04/VWJVH825FTDDN6YlKLdJ5Vy1W6mk3Cf5HxRnbN8XrLGM3qn9qW95jsWP6lZ3lwW=\r\n51BBFz8ySRQ9W1Xv_F579CBk_N7TDKKWnyTLPW28lCXQ661c_qW2DkhBX4FT993W5_lCc33GM45=\r\ntW1v3wx16qbbCWW7Gbn7y6l2wZ7W7BHthm4Bd8gZW6W9Q333P05z6W7js_Cd8jRF1xW1ZCMb77z=\r\nWJjNW3nJnP33C-G5WW34zBP-4RqlN7W8Vm5Yv6SzkTwW29tCsd1nS4j_W3cStvc8JS32sN93zs3=\r\n1CmV3_W3wR6535j714TVmt_jv5bV8VzW55MXdx4zgK_KW2PLxgC1gXTxFW1X1F_x46Y4PHM94H5=\r\nXWlZ7BN5Np8vFXmNtCW7dZfPW4h9Zw5VPkHqc3GrvGFW4bYGl-2lGdtqN6xtv5bTP49MW8FGKlt=\r\n62nLYNdQ93hF04\" style=3D\"color:#0000ee\" data-hs-link-id=3D\"0\" data-hs-link-=\r\nid-v2=3D\"iLbQRzwH\" target=3D\"_blank\">negativity bias</a>, and it=E2=80=99s =\r\ndoing what it does best.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">I bet most of you already know <em>exactly</em> what I\'m talking about.<=\r\n/span></p></div></div></td></tr></tbody></table>\r\n<div id=3D\"hs_cos_wrapper_module-1-0-3\" class=3D\"hs_cos_wrapper hs_cos_wrap=\r\nper_widget hs_cos_wrapper_type_module\" style=3D\"color: inherit; font-size: =\r\ninherit; line-height: inherit;\" data-hs-cos-general-type=3D\"widget\" data-hs=\r\n-cos-type=3D\"module\"><table class=3D\"hse-image-wrapper\" role=3D\"presentatio=\r\nn\" width=3D\"100%\" cellpadding=3D\"0\" cellspacing=3D\"0\">\r\n  <tbody>\r\n    <tr>\r\n      <td class=3D\"hs_padded\" align=3D\"center\" valign=3D\"top\" style=3D\"font=\r\n-family:Arial, sans-serif; color:#000000; word-break:break-word; text-align=\r\n:center; padding:10px 20px; font-size:0px\">\r\n        <img alt=3D\"Screenshot of Ramits post about opportunity\" src=3D\"htt=\r\nps://hs-43794645.f.hubspotemail.net/hub/43794645/hubfs/Screenshot%20of%20Ra=\r\nmits%20post%20about%20opportunity.png?width=3D1000&amp;upscale=3Dtrue&amp;n=\r\name=3DScreenshot%20of%20Ramits%20post%20about%20opportunity.png\" style=3D\"o=\r\nutline:none; text-decoration:none; max-width:100%; font-size:16px; border-r=\r\nadius:10px\" width=3D\"500\" align=3D\"middle\">\r\n      </td>\r\n    </tr>\r\n  </tbody>\r\n</table></div>\r\n  <table role=3D\"presentation\" cellpadding=3D\"0\" cellspacing=3D\"0\" width=3D=\r\n\"100%\" class=3D\"\" style=3D\"\"><tbody><tr><td class=3D\"hs_padded\" style=3D\"fo=\r\nnt-family:Arial, sans-serif; font-size:18px; color:#000000; word-break:brea=\r\nk-word; padding:10px 20px\"><div id=3D\"hs_cos_wrapper_module-1-0-4\" class=3D=\r\n\"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module\" style=3D\"=\r\ncolor: inherit; font-size: inherit; line-height: inherit;\" data-hs-cos-gene=\r\nral-type=3D\"widget\" data-hs-cos-type=3D\"module\"><div id=3D\"hs_cos_wrapper_m=\r\nodule-1-0-4_\" class=3D\"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_=\r\ntype_rich_text\" style=3D\"color: inherit; font-size: inherit; line-height: i=\r\nnherit;\" data-hs-cos-general-type=3D\"widget\" data-hs-cos-type=3D\"rich_text\"=\r\n><p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #00000=\r\n0;\">It\'s why you remember that one criticism in a sea of compliments. Why y=\r\nou obsess over the $200 dinner instead of the $20,000 you invested this yea=\r\nr.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">Your brain defaults to negative.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">But you can train it to stop.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<h2 style=3D\"margin:0; font-family:Georgia, serif; font-size:28px; line-hei=\r\nght:150%\"><span style=3D\"color: #000000;\">3 steps to overcome your negativi=\r\nty bias</span></h2>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\"><strong>Step 1: Notice the negative thought</strong></span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">Next time you react to an idea, like \"I could start a business in 2026,=\r\n=E2=80=9D pause. Notice what thoughts immediately pop up.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\"><strong><em>\"I don\'t have time.\" \"What if I fail?\" \"I\'m not ready.\"</em>=\r\n</strong></span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">Don\'t judge the thoughts. Just notice them.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\"><strong>Step 2: Separate the feeling from the thought</strong></span></p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">You <em>feel</em> scared about starting a business. So your brain scramb=\r\nles to hand you \"logical\" reasons not to do it.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%\">&nbsp;</p>\r\n<p style=3D\"font-size:18px; line-height:175%\"><span style=3D\"color: #000000=\r\n;\">But you\'re confusing a <strong>feeling</strong> (fear of failure) with a=\r\n <strong>thought</strong> (reasons you shouldn\'t start).</span></p></div></=\r\ndiv></td></tr></tbody></table>\r\n<div id=3D\"hs_cos_wrapper_module-1-0-5\" class=3D\"hs_cos_wrapper hs_cos_wrap=\r\nper_widget hs_cos_wrapper_type_module\" style=3D\"color: inherit; font-size: =\r\ninherit; line-height: inherit;\" data-hs-cos-general-type=3D\"widget\" data-hs=\r\n-cos-type=3D\"module\"><table class=3D\"hse-image-wrapper\" role=3D\"presentatio=\r\nn\" width=3D\"100%\" cellpadding=3D\"0\" cellspacing=3D\"0\">\r\n  <tbody>\r\n    <tr>\r\n      <td class=3D\"hs_padded\" align=3D\"center\" valign=3D\"top\" style=3D\"font=\r\n-family:Arial, sans-serif; color:#000000; word-break:break-word; text-align=\r\n:center; padding:10px 20px; font-size:0px\">\r\n        <img alt=3D\"Ahhh!\" src=3D\"https://hs-43794645.f.hubspotemail.net/hu=\r\nb/43794645/hubfs/Ahhh!.gif?width=3D900&amp;upscale=3Dtrue&amp;name=3DAhhh!.=\r\ngif\" style=3D\"outline:none; text-decoration:none; max-width:100%; font-size=\r\n:16px; border-radius:10px\" width=3D\"450\" align=3D\"middle\">\r\n      </td>\r\n    </tr>\r\n  </tbody>\r\n</table></div>\r\n  <table role=3D\"presentation\" cellpadding=3D\"0\" cellspacing=3D\"0\" width=3D=\r\n\"100%\" class=3D\"\" style=3D\"\"><tbody><tr><td class=3D\"hs_padded\" style=3D\"fo=\r\nnt-family:Arial, sans-serif; font-size:18px; color:#000000; word-break:brea=\r\nk-word; padding:0px 20px\"><div id=3D\"hs_cos_wrapper_module-1-0-6\" class=3D\"=\r\nhs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_type_module\" style=3D\"c=\r\nolor: inherit; font-size: inherit; line-height: inherit;\" data-hs-cos-gener=\r\nal-type=3D\"widget\" data-hs-cos-type=3D\"module\"><div id=3D\"hs_cos_wrapper_mo=\r\ndule-1-0-6_\" class=3D\"hs_cos_wrapper hs_cos_wrapper_widget hs_cos_wrapper_t=\r\nype_rich_text\" style=3D\"color: inherit; font-size: inherit; line-height: in=\r\nherit;\" data-hs-cos-general-type=3D\"widget\" data-hs-cos-type=3D\"rich_text\">=\r\n<p style=3D\"text-align:center; font-size:18px; line-height:150%; font-weigh=\r\nt:normal\" align=3D\"center\"><span style=3D\"color: #000000;\"><em>Your brain f=\r\nrantically Googling reasons why you shouldn\'t do&nbsp;the&nbsp;thing.</em><=\r\n/span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">Thoughts are just ideas.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">On their own, they=E2=80=99re neutral.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">They only gain power when you attach them to feeling=\r\ns =E2=80=94 fear, shame, urgency, excitement.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">Separate the two, and you get your leverage back.</s=\r\npan></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">That leverage is the difference between reacting emo=\r\ntionally and choosing deliberately.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">When your thought isn=E2=80=99t attached to a feelin=\r\ng, you get to decide whether it deserves action =E2=80=94 or whether it=E2=\r\n=80=99s just noise.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:bold\"><span style=\r\n=3D\"color: #000000;\">Step 3: Decide what to do with the thought</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">A therapist once told me: <em>\"You can\'t keep a thou=\r\nght from entering your mind, but you don\'t have to sit it down and serve it=\r\n dinner.\"</em></span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">Once you\'ve noticed the thought and separated the fe=\r\neling, ask yourself:</span></p>\r\n<ul style=3D\"font-size:18px; color:#000000; line-height:175%\">\r\n<li style=3D\"font-weight: normal; color: #000000; padding-bottom: 10px;\">Is=\r\n this thought actually valid?</li>\r\n<li style=3D\"font-weight: normal; color: #000000; padding-bottom: 10px;\">Wh=\r\nat if things went the exact opposite way?</li>\r\n<li style=3D\"font-weight: normal; color: #000000; padding-bottom: 10px;\">Wh=\r\nat if this went <em>really, really</em> well?</li>\r\n</ul>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">Look, our brains are wired for negativity bias. And =\r\nrewiring these patterns takes practice. A lot of it.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">It=E2=80=99s much easier when you=E2=80=99re not doi=\r\nng it alone.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">When you have a community and coaching, you=E2=80=99=\r\nre surrounded by people working on the same things. You can ask questions, =\r\nget feedback, and have someone catch you before you spiral or quit.</span><=\r\n/p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">That=E2=80=99s exactly why so many of you keep askin=\r\ng when <a href=3D\"https://d586LZ04.na1.hubspotlinks.com/Ctc/W5+113/d586LZ04=\r\n/VWJVH825FTDDN6YlKLdJ5Vy1W6mk3Cf5HxRnbN8XrLDH5nXHCW50kH_H6lZ3lmVqyyfY1k2yK8=\r\nW8qlcnC4rvbl6VNY6444-T3fjW3fQYnH8s2WfmW935D1Y6966lHW6chmvb3kCq3GW5QRyRL2gSX=\r\nR_W2P9x497Qf4rKW5Bxhc78hpHW0W7dXxXX4d3M9VW6NxBgQ50lt9nW18KL3m7BPwmMW5_-yWX3=\r\nY6zGbN3wnzyF4dQ2qW4NxDXP5xlr3XW5R4twd2PKhB4W4rC41D6l54-bW5_pnwK3SlhfqW7Bf7c=\r\nl19pQSfVKkkGg3F-TfWW5wpCgh6DpsPFW3FqK6p8wlSbFMyRpbtQ8rG7VhHl0b7jT0xqW3fm6bH=\r\n1xGn2nW7WTcp78cD30zW1KYWWq4syC6mW7W2b9S4t-F6ZW1-ZkZh3N0NDsW48Q-Hj13NvCCW23R=\r\nk6G7ZjDmqW2zFHrS9bRm98f1tm7GP04\" rel=3D\"noopener\" style=3D\"color:#0000ee\" d=\r\nata-hs-link-id=3D\"0\" data-hs-link-id-v2=3D\"OmB292oS\" target=3D\"_blank\"><em>=\r\nEarnable Live</em></a> opens again. I only open it up a few times a year.</=\r\nspan></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">It=E2=80=99s my program for building a profitable bu=\r\nsiness with a proven system =E2=80=94 alongside a live cohort and community=\r\n.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\">You get direct support from my team so you can push =\r\nthrough roadblocks instead of getting stuck.</span></p>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\">&nbsp;</p=\r\n>\r\n<p style=3D\"font-size:18px; line-height:175%; font-weight:normal\"><span sty=\r\nle=3D\"color: #000000;\"><a href=3D\"https://d586LZ04.na1.hubspotlinks.com/Ctc=\r\n/W5+113/d586LZ04/V